int cls(char *p,int *n){wchar_t c;*n=mbtowc(&c,p,4);if(*n<1)*n=1,c=(unsigned char)*p;return cat(c);}
void emit(int t){if(t<256)putchar(raw[t]);else if(t<50256)emit(L[t]),emit(R[t]);else fputs("<|endoftext|>",stdout);}
void norm(float *o,float *b,float *g){float m=0,r=0;for(int i=0;i<D;i++)m+=x[i]/D;for(int i=0;i<D;i++)r+=(x[i]-m)*(x[i]-m)/D;r=1/sqrtf(r+1e-5f);for(int i=0;i<D;i++)o[i]=(x[i]-m)*r*g[i]+b[i];}
